mapper.select:
SELECT prod_date AS date, SUM(qty) AS total
FROM production_log
WHERE EXTRACT(YEAR FROM prod_date) = #{year}
  AND EXTRACT(MONTH FROM prod_date) = #{month}
GROUP BY prod_date
ORDER BY prod_date

SELECT COALESCE(SUM(qty),0)
FROM production_log
WHERE EXTRACT(YEAR FROM prod_date) = #{year}
  AND EXTRACT(MONTH FROM prod_date) = #{month}
